#!/usr/bin/env node
/*
 * Packaged-artifact Claude Code E2E validator (fixture-only).
 *
 * Validates the packed skill-router artifact against an installed Claude Code CLI (2.x).
 * Skill discovery for the generated router skill is exercised only through the
 * production plugin generated by `skill-router init --harness claude` and passed
 * via `--plugin-dir`: the plugin is router-owned inert metadata
 * (`.claude-plugin/plugin.json` + generated `skills/` trees) under the production
 * namespace, so this script never installs into host Claude configuration, never
 * creates a persistent Claude adapter, and never builds a plugin of its own.
 * Registration runs only against fixture-local HOME/CLAUDE_CONFIG_DIR/scratch
 * surfaces and is never visible to the model runs.
 *
 * Contract (fail-fast before packing): SKILL_ROUTER_CLAUDE_BIN (default "claude"),
 * SKILL_ROUTER_CLAUDE_MODEL (required), and SKILL_ROUTER_CLAUDE_API_KEY or
 * ANTHROPIC_API_KEY (one required).
 *
 * Isolation: `claude -p --bare --output-format stream-json --verbose
 * --no-session-persistence` under an allowlisted environment whose only credential is
 * the isolated API key; HOME/CLAUDE_CONFIG_DIR/TMPDIR are fixture-local; the permission
 * allowlist covers Skill, Write, and the Bash route command, with a defensive `mcp__*`
 * denial, and only routed runs receive `--plugin-dir` (documented to work under `--bare`;
 * control never receives it). Assertions are structural over parsed NDJSON — exact
 * inert-plugin layout, exact plugin system/init tuples, canonical namespaced Skill IDs —
 * and all failure text flows through the central sanitizeText redaction so raw
 * stdout/stderr, credentials, session IDs, and repository/home/fixture paths are never
 * emitted. KEEP_FIXTURE=1 (or SKILL_ROUTER_KEEP_FIXTURE=1) retains scrubbed content only;
 * credential-bearing files are always removed.
 */

import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { createHash } from "node:crypto";
import { accessSync, constants, existsSync, mkdirSync, mkdtempSync, readdirSync, readFileSync, realpathSync, rmSync, writeFileSync } from "node:fs";
import os from "node:os";
import path from "node:path";
import process from "node:process";
import { fileURLToPath } from "node:url";
// Single source of truth for the production plugin namespace, plugin paths,
// inert-manifest key set, and the canonical namespaced Skill IDs: the container
// case runner derives all of them from the installed package, and this script
// only consumes the plugin the packaged CLI generated.
import {
  CLAUDE_RELEASE_SKILL_ID,
  CLAUDE_ROUTER_SKILL_ID,
  PLUGIN_MANIFEST_KEYS,
  PLUGIN_NAME,
  PLUGIN_ROOT_ENTRIES,
  RELEASE_SKILL_ID,
  ROUTER_SKILL_ID,
} from "./container-run-case.mjs";

const repository = path.dirname(path.dirname(fileURLToPath(import.meta.url)));
const UUID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const RELEASE_MARKER = "RELEASE_SKILL_LOADED";
const TOKEN_FILE_PATTERN = /\.skill-router\/requests\/([a-f0-9]{32})\.txt$/;
// Every Skill tool use in this fixture is one of these canonical namespaced IDs
// (generated plugin) or one of the bare managed IDs (never acceptable once loaded).
const ROUTER_SKILL_ALIASES = new Set([CLAUDE_ROUTER_SKILL_ID, ROUTER_SKILL_ID]);
const RELEASE_SKILL_ALIASES = new Set([CLAUDE_RELEASE_SKILL_ID, RELEASE_SKILL_ID]);
// Pinned Claude Code 2.1.291 builtins that are always reported in
// system/init.plugins, independent of this fixture's generated plugin.
const PINNED_BUILTIN_PLUGINS = Object.freeze([
  { name: "cc-plugin-agents-md", path: "builtin" },
  { name: "cc-plugin-plugin-authoring", path: "builtin" },
]);
// Nonessential/networked/side-effect tools are denied explicitly; unknown
// names are inert deny rules. The permission allowlist enforces the runtime
// minimum, and `mcp__*` denies every MCP tool on top of the empty MCP state.
const DISALLOWED_TOOLS =
  "WebFetch,WebSearch,Edit,MultiEdit,NotebookEdit,NotebookRead,TodoWrite,Task,TaskCreate,TaskGet,TaskList,TaskOutput,TaskStop,TaskUpdate,Agent,PushNotification,CronCreate,CronDelete,CronUpdate,ScheduleWakeup,RemoteTrigger,DesignSync,EnterWorktree,ExitWorktree,Monitor,KillShell,EnterPlanMode,ExitPlanMode,mcp__*";
const ALLOWED_TOOLS = "Skill,Write,Bash(skill-router route:*)";
const RUN_TIMEOUT_MS = 300_000;
const MAX_BUFFER = 64 * 1024 * 1024;

const CONTROL_PROMPT = `Use the Skill tool to load the skill named ${CLAUDE_ROUTER_SKILL_ID}, then use it for this request: ` +
  "prepare and publish a release. If the skill cannot be loaded, report that it is unavailable and stop.";
const RELEASE_PROMPT = `Load and use the \`${CLAUDE_ROUTER_SKILL_ID}\` skill for this request: prepare and publish a release. Route exactly the request text ` +
  '"prepare and publish a release". After loading the selected skill, return the marker that its instructions tell you to return.';
const UNRELATED_PROMPT = `Load and use the \`${CLAUDE_ROUTER_SKILL_ID}\` skill for this unrelated request: calculate orbital velocity. Route exactly the ` +
  'request text "calculate orbital velocity". Report only the router outcome.';

// Fail-fast configuration gate (before any fixture or packing work).
const claudeSetting = process.env.SKILL_ROUTER_CLAUDE_BIN || "claude";
const model = (process.env.SKILL_ROUTER_CLAUDE_MODEL || "").trim();
const credential = (process.env.SKILL_ROUTER_CLAUDE_API_KEY || process.env.ANTHROPIC_API_KEY || "").trim();
const keepFixture = process.env.SKILL_ROUTER_KEEP_FIXTURE === "1" || process.env.KEEP_FIXTURE === "1";

function gateError(message) {
  const error = new Error(message);
  error.code = "E2E_GATE";
  return error;
}

function resolveExecutable(setting) {
  const explicit = setting.includes("/") || setting.includes("\\");
  const search = explicit
    ? [path.resolve(setting)]
    : (process.env.PATH || "").split(path.delimiter).filter(Boolean).map((dir) => path.join(dir, setting));
  for (const candidate of search) {
    try {
      accessSync(candidate, constants.X_OK);
      return candidate;
    } catch {
      // Keep searching the remaining candidates.
    }
  }
  throw gateError(explicit
    ? `SKILL_ROUTER_CLAUDE_BIN is missing or not executable: ${path.basename(setting)}`
    : "SKILL_ROUTER_CLAUDE_BIN was not found on PATH; install Claude Code or point SKILL_ROUTER_CLAUDE_BIN at the binary");
}

// Fixture state, populated after the gate passes.
const fx = {};

// Central sanitized failure reporting: raw stderr/stdout, credentials,
// session IDs, request tokens, and repo/home/fixture paths never reach logs.
function sanitizeText(value) {
  if (typeof value !== "string" || value === "") return "";
  let result = credential ? value.split(credential).join("[redacted-credential]") : value;
  const hostHome = process.env.HOME || os.homedir();
  result = result
    .replace(/sk-ant-[A-Za-z0-9_-]{8,}/g, "[redacted-credential]")
    .replace(/Bearer\s+\S+/gi, "Bearer [redacted]")
    .replace(/\bAuthorization["']?\s*[:=]\s*(?:"[^"]*"|\S+)/gi, "Authorization: [redacted]")
    .replace(/\beyJ[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}\b/g, "[redacted-jwt]")
    .replace(/\b(?:sk|pat|api|key|token|secret|auth|password|passwd|bearer)[-_:][A-Za-z0-9_./+=-]{8,}\b/gi, "[redacted]")
    .replace(/\b(?:api[_-]?key|access[_-]?token|refresh[_-]?token|id[_-]?token|client[_-]?secret|secret|password|passwd|token|credential)["']?\s*[:=]\s*["']?[^\s"',;)}\]]+/gi, (match) => `${match.slice(0, match.search(/[:=]/) + 1)} [redacted]`)
    .replace(/\bses_[A-Za-z0-9]+\b/g, "ses_[redacted]")
    .replace(/\b[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\b/gi, "[uuid]")
    .replace(/\b[a-f0-9]{32}\b/g, "[request-token]");
  if (fx.temporary) result = result.split(fx.temporary).join("[fixture]");
  result = result.split(repository).join("[repository]");
  if (hostHome.length > 1) result = result.split(hostHome).join("[home]");
  return result;
}

// Structural summary of stream-json stdout (event kinds, tool_use names,
// sanitized messages) for failure display only. Never the raw payload.
function summarizeStream(output) {
  if (typeof output !== "string" || output.trim() === "") return "stdout: empty";
  const lines = output.trim().split(/\r?\n/);
  const kinds = [];
  const tools = [];
  const messages = new Set();
  let parsed = 0;
  for (const line of lines) {
    let event;
    try {
      event = JSON.parse(line);
    } catch {
      continue;
    }
    parsed += 1;
    if (!event || typeof event !== "object") continue;
    const kind = typeof event.type === "string" ? (typeof event.subtype === "string" ? `${event.type}/${event.subtype}` : event.type) : `type:${typeof event.type}`;
    if (!kinds.includes(kind) && kinds.length < 24) kinds.push(kind);
    for (const block of Array.isArray(event.message?.content) ? event.message.content : []) {
      if (block?.type === "tool_use" && typeof block.name === "string" && !tools.includes(block.name) && tools.length < 24) tools.push(block.name);
    }
    for (const key of ["error", "message", "result"]) {
      if (typeof event[key] === "string" && messages.size < 6) messages.add(event[key]);
    }
  }
  const summary = [
    parsed ? `stream events: ${parsed}` : null,
    kinds.length ? `event kinds: ${kinds.join(", ")}` : null,
    tools.length ? `tool_use names: ${tools.join(", ")}` : null,
    ...[...messages].map((message) => `event message: ${sanitizeText(message).slice(0, 400)}`),
    parsed < lines.length ? `non-JSON stdout lines: ${lines.length - parsed}` : null,
  ].filter(Boolean).join("\n");
  return sanitizeText(summary) || "stdout: no parseable stream events";
}

// Single failure-reporting path for spawned commands.
function describeFailure(file, args, result) {
  const parts = [
    result.error ? `spawn error: ${result.error.code || result.error.message}` : null,
    result.signal ? `signal: ${result.signal}` : null,
    typeof result.status === "number" && !result.error && !result.signal ? `exit status ${result.status}` : null,
    sanitizeText(result.stderr || "").slice(-4000),
    summarizeStream(result.stdout),
  ].filter(Boolean);
  const label = path.basename(String(file));
  const invocation = args.map((argument) => sanitizeText(String(argument)).slice(0, 120)).join(" ");
  return sanitizeText(`${label} ${invocation} failed\n${parts.join("\n")}`.trim());
}

function reportFailure(error) {
  const raw = error && error.code === "E2E_GATE" ? String(error.message) : String(error?.stack || error);
  process.stderr.write(`claude-e2e failed:\n${sanitizeText(raw)}\n`);
}

function section(title) {
  process.stdout.write(`\n=== ${title} ===\n`);
}

// Spawn helpers.
function execute(file, args, options = {}) {
  const result = spawnSync(file, args, {
    cwd: options.cwd ?? repository, env: options.env ?? process.env, encoding: "utf8",
    timeout: options.timeout ?? 120_000, maxBuffer: MAX_BUFFER, input: options.input,
  });
  if (options.expectFailure) assert.notEqual(result.status, 0, `${path.basename(String(file))} unexpectedly succeeded`);
  else assert.equal(result.status, 0, describeFailure(file, args, result));
  return result;
}

// Allowlisted child environment: isolated HOME/TMPDIR/config, host PATH (so
// the router bin and node resolve), and ONLY the isolated API key credential.
function claudeEnvironment() {
  return {
    PATH: [fx.routerBin, process.env.PATH].filter(Boolean).join(path.delimiter),
    HOME: fx.home, TMPDIR: fx.fixtureTmp, PWD: fx.project,
    SHELL: process.env.SHELL || "/bin/sh", LANG: process.env.LANG || "en_US.UTF-8",
    CLAUDE_CONFIG_DIR: path.join(fx.home, ".claude"), ANTHROPIC_API_KEY: credential, SKILL_ROUTER_HOME: fx.home,
    CLAUDE_CODE_DISABLE_NONESSENTIAL_TRAFFIC: "1", CLAUDE_CODE_DISABLE_SKILLS_SYNC: "1",
    DISABLE_TELEMETRY: "1", DISABLE_AUTOUPDATER: "1", DISABLE_ERROR_REPORTING: "1", DISABLE_BUG_COMMAND: "1",
  };
}

// The production plugin is only reachable through `--plugin-dir` (documented to
// work under `--bare`); the control run receives neither it nor any
// settings-based plugin source, so its plugin state must stay at the pinned
// builtins alone.
function runClaude(prompt, withPlugin) {
  const args = [
    "-p", "--bare", "--output-format", "stream-json", "--verbose", "--no-session-persistence",
    "--model", model, "--permission-mode", "default",
    "--allowedTools", ALLOWED_TOOLS, "--disallowedTools", DISALLOWED_TOOLS,
  ];
  if (withPlugin) args.push("--plugin-dir", fx.pluginDir);
  return execute(fx.claude, args, { cwd: fx.project, env: claudeEnvironment(), input: prompt, timeout: RUN_TIMEOUT_MS });
}

// Fixture skills, plugin layout checks, deterministic content assertions.
function writeSkill(directory, id, name, description, marker) {
  const target = path.join(directory, id);
  mkdirSync(target, { recursive: true });
  writeFileSync(path.join(target, "SKILL.md"), `---\nname: ${name}\ndescription: ${description}\n---\n\n# ${name}\n\nWhen loaded, return ${marker}.\n`);
}

function frontmatterName(text) {
  const match = String(text).replaceAll("\r\n", "\n").match(/^---\n([\s\S]*?)\n---\n?/);
  if (!match) return null;
  const nameLine = match[1].split("\n").find((line) => /^name:/.test(line));
  if (!nameLine) return null;
  let value = nameLine.replace(/^name:\s*/, "").trim();
  if (value.startsWith('"')) {
    try {
      value = JSON.parse(value);
    } catch {
      return null;
    }
  } else if (value.startsWith("'")) value = value.slice(1, -1).replaceAll("''", "'");
  return typeof value === "string" ? value.trim() : null;
}

function sortedEntries(root) {
  return readdirSync(root, { withFileTypes: true }).sort((a, b) => a.name.localeCompare(b.name));
}

// Relative-path -> sha256 manifest; dotfiles are ignored symmetrically on
// both sides so environmental noise cannot fake a mismatch.
function treeManifest(root) {
  const entries = [];
  const visit = (directory, relative) => {
    for (const entry of sortedEntries(directory)) {
      if (entry.name.startsWith(".")) continue;
      const relativePath = relative ? `${relative}/${entry.name}` : entry.name;
      const absolute = path.join(directory, entry.name);
      if (entry.isSymbolicLink()) throw new Error(`unexpected symlink in fixture skill tree: ${entry.name}`);
      if (entry.isDirectory()) visit(absolute, relativePath);
      else if (entry.isFile()) entries.push([relativePath, createHash("sha256").update(readFileSync(absolute)).digest("hex")]);
      else throw new Error(`unexpected non-file entry in fixture skill tree: ${entry.name}`);
    }
  };
  visit(root, "");
  return Object.fromEntries(entries);
}

function listingIds(root) {
  return sortedEntries(root).map((entry) => {
    if (entry.isSymbolicLink()) throw new Error(`unexpected symlink in skill listing: ${entry.name}`);
    if (entry.isDirectory()) return entry.name;
    if (entry.isFile() && entry.name.endsWith(".md")) return entry.name.slice(0, -3);
    throw new Error(`unexpected entry in skill listing: ${entry.name}`);
  }).sort();
}

// Exact layout of the *generated* plugin: the root carries exactly
// `.claude-plugin/` and `skills/`, `.claude-plugin/` carries exactly
// `plugin.json`, the skills directory is populated, and the manifest is inert
// metadata under the production namespace. This script never writes any of it —
// `skill-router init --harness claude` does.
function assertPluginLayout(pluginDir, expected = {}) {
  const names = (root) => sortedEntries(root).map((entry) => {
    if (entry.isSymbolicLink()) throw new Error(`unexpected symlink in generated plugin: ${entry.name}`);
    return entry.name;
  });
  assert.deepEqual(names(pluginDir), [...PLUGIN_ROOT_ENTRIES], "generated plugin root must carry exactly .claude-plugin/ and skills/");
  assert.deepEqual(names(path.join(pluginDir, ".claude-plugin")), ["plugin.json"], ".claude-plugin must carry exactly plugin.json");
  assert.ok(sortedEntries(path.join(pluginDir, "skills")).length > 0, "generated plugin skills/ directory is empty");
  let manifest;
  try {
    manifest = JSON.parse(readFileSync(path.join(pluginDir, ".claude-plugin", "plugin.json"), "utf8"));
  } catch (error) {
    throw new Error(`generated plugin manifest is not valid JSON: ${sanitizeText(error.message).slice(0, 200)}`);
  }
  assert.deepEqual(Object.keys(manifest).sort(), [...PLUGIN_MANIFEST_KEYS].sort(),
    "generated plugin manifest must carry inert metadata only (no paths/deps/settings/hooks/executable declarations)");
  assert.equal(manifest.name, PLUGIN_NAME, "generated plugin manifest carries the wrong plugin namespace");
  if (expected.version !== undefined) {
    assert.equal(manifest.version, expected.version, "manifest version must match installation metadata");
  }
}

// Strict structural NDJSON stream parsing (no raw-text searching).
function parseStreamEvents(output, label) {
  const trimmed = typeof output === "string" ? output.trim() : "";
  assert.ok(trimmed, `${label}: Claude produced no stream events on stdout`);
  return trimmed.split(/\r?\n/).map((line, index) => {
    try {
      return JSON.parse(line);
    } catch (error) {
      throw new Error(`${label}: stream line ${index + 1} is not valid JSON: ${sanitizeText(error.message).slice(0, 200)}`);
    }
  });
}

function contentBlocks(event, type) {
  if (event?.type !== type || !Array.isArray(event.message?.content)) return [];
  return event.message.content.filter((block) => block && typeof block === "object");
}

function toolUses(events) {
  const uses = [];
  events.forEach((event, index) => {
    for (const block of contentBlocks(event, "assistant")) {
      if (block.type === "tool_use") uses.push({ index, id: block.id, name: block.name, input: block.input });
    }
  });
  return uses;
}

function toolResults(events) {
  const results = new Map();
  events.forEach((event, index) => {
    for (const block of contentBlocks(event, "user")) {
      if (block.type !== "tool_result") continue;
      const content = block.content;
      const text = typeof content === "string" ? content
        : Array.isArray(content) ? content.map((part) => (typeof part === "string" ? part : typeof part?.text === "string" ? part.text : "")).join("") : "";
      results.set(block.tool_use_id, { index, isError: block.is_error === true, text });
    }
  });
  return results;
}

function assistantTexts(events) {
  const texts = [];
  events.forEach((event, index) => {
    for (const block of contentBlocks(event, "assistant")) {
      if (block.type === "text" && typeof block.text === "string") texts.push({ index, text: block.text });
    }
  });
  return texts;
}

function skillName(input) {
  if (!input || typeof input !== "object") return null;
  const firstString = Object.values(input).find((value) => typeof value === "string" && value.trim());
  return firstString ? firstString.trim().replace(/^\/+/, "").split(/\s+/)[0] : null;
}

function assertEmptyReportedKeys(init, pattern, what, label) {
  const keys = Object.keys(init).filter((key) => pattern.test(key));
  assert.ok(keys.length > 0, `${label}: system/init did not report ${what}`);
  const empty = (value) => value == null || value === false || value === 0 ||
    (typeof value === "string" && value.trim() === "") ||
    (Array.isArray(value) && value.length === 0) ||
    (typeof value === "object" && Object.keys(value).length === 0);
  for (const key of keys) {
    assert.ok(empty(init[key]), `${label}: system/init reported ${what} under "${key}": ${sanitizeText(JSON.stringify(init[key])).slice(0, 200)}`);
  }
}

// Skills-shaped inventories in system/init (slash command lists are included
// because they mirror skill discovery in some CLI builds).
function skillsInventory(init) {
  const lists = {};
  for (const [key, value] of Object.entries(init)) {
    if (key !== "slash_commands" && !/^skill/i.test(key)) continue;
    if (Array.isArray(value)) {
      lists[key] = value.map((entry) => (typeof entry === "string" ? entry.replace(/^\/+/, "").trim() : typeof entry?.name === "string" ? entry.name : "")).filter(Boolean);
    } else if (value && typeof value === "object") {
      lists[key] = Object.keys(value).map((entry) => entry.replace(/^\/+/, ""));
    }
  }
  return lists;
}

// Exact source path for one plugin tuple: `builtin` (and any other literal)
// must match verbatim, while the generated plugin directory may be reported through a
// symlink-resolved path — either way the report must resolve to this run's
// plugin directory.
function sameSourcePath(reportedPath, expectedPath) {
  if (reportedPath === expectedPath) return true;
  if (typeof reportedPath !== "string" || typeof expectedPath !== "string") return false;
  if (reportedPath === "builtin" || expectedPath === "builtin") return false;
  try {
    return realpathSync(reportedPath) === realpathSync(expectedPath);
  } catch {
    return false;
  }
}

// Exact plugin state for this run: the two pinned Claude builtins always,
// plus the generated plugin — reported as `{name, path:<dynamic plugin
// directory>}` — only when `--plugin-dir` was passed. Control therefore proves its
// plugin surface is exactly the pinned builtins, and any other plugin-shaped
// key must stay empty.
function assertPluginState(init, pluginDir, label) {
  const pluginKeys = Object.keys(init).filter((key) => /plugin/i.test(key));
  assert.ok(pluginKeys.includes("plugins"), `${label}: system/init did not report plugins`);
  for (const key of pluginKeys) {
    if (key === "plugins") continue;
    assert.ok(init[key] == null || (typeof init[key] === "object" && Object.keys(init[key]).length === 0),
      `${label}: system/init reported plugin state under "${key}"`);
  }
  const reported = init.plugins;
  assert.ok(Array.isArray(reported), `${label}: system/init plugins was not an array`);
  const expected = [...PINNED_BUILTIN_PLUGINS, ...(pluginDir ? [{ name: PLUGIN_NAME, path: pluginDir }] : [])];
  const tuples = (list) => list.map((entry) => {
    assert.ok(entry && typeof entry === "object" && typeof entry.name === "string" && typeof entry.path === "string",
      `${label}: system/init plugin entry is not a {name,path} tuple`);
    return { name: entry.name, path: entry.path };
  });
  const reportedTuples = tuples(reported);
  // Names first (structural, never paths), then the exact source path per
  // plugin: `builtin` for the pinned ones, the generated plugin directory for ours.
  assert.deepEqual(reportedTuples.map((entry) => entry.name).sort(), expected.map((entry) => entry.name).sort(),
    `${label}: system/init reported an unexpected plugin set`);
  const reportedPaths = new Map(reportedTuples.map((entry) => [entry.name, entry.path]));
  for (const entry of expected) {
    assert.ok(sameSourcePath(reportedPaths.get(entry.name), entry.path),
      `${label}: system/init plugin "${entry.name}" reported "${sanitizeText(String(reportedPaths.get(entry.name)))}" instead of its expected source path`);
  }
}

function inspectInit(events, label, pluginDir = null) {
  const inits = events.filter((event) => event?.type === "system" && event?.subtype === "init");
  assert.equal(inits.length, 1, `${label}: expected exactly one system/init event, saw ${inits.length}`);
  const init = inits[0];
  const initIndex = events.indexOf(init);
  const sessionId = init.session_id;
  assert.ok(typeof sessionId === "string" && UUID_PATTERN.test(sessionId), `${label}: system/init session_id is not a UUID`);
  const sessionIds = new Set(events.map((event) => event?.session_id).filter(Boolean));
  assert.equal(sessionIds.size, 1, `${label}: stream reported ${sessionIds.size} distinct session IDs`);
  assert.ok(sessionIds.has(sessionId), `${label}: system/init session_id missing from stream session IDs`);
  assertEmptyReportedKeys(init, /mcp/i, "MCP server state", label);
  assertPluginState(init, pluginDir, label);
  assert.ok(!toolUses(events).some((use) => typeof use.name === "string" && use.name.startsWith("mcp__")),
    `${label}: stream used an MCP tool despite empty MCP state`);
  const tools = new Set();
  for (const entry of Array.isArray(init.tools) ? init.tools : []) {
    if (typeof entry === "string") tools.add(entry);
    else if (entry && typeof entry.name === "string") tools.add(entry.name);
  }
  for (const required of ["Skill", "Write", "Bash"]) {
    assert.ok(tools.has(required), `${label}: system/init tools missing ${required} (available: ${[...tools].sort().join(", ")})`);
  }
  return { initIndex, sessionId, inventory: skillsInventory(init) };
}

function assertResultSuccess(events, label) {
  const results = events.filter((event) => event?.type === "result");
  assert.equal(results.length, 1, `${label}: expected exactly one result event, saw ${results.length}`);
  const [result] = results;
  const detail = sanitizeText(JSON.stringify({ subtype: result.subtype, is_error: result.is_error }));
  assert.ok(result.subtype === "success" && result.is_error !== true, `${label}: run did not finish successfully (${detail})`);
}

function successfulSkillUse(events, results, skillId, label, afterIndex = -1) {
  const candidates = toolUses(events).filter((use) => use.index > afterIndex && use.name === "Skill" && skillName(use.input) === skillId);
  const success = candidates.find((use) => {
    const result = results.get(use.id);
    return result && result.isError !== true;
  });
  assert.ok(success, `${label}: agent did not complete Skill(${skillId}) with a successful tool_result after the required prior step`);
  return success;
}

// Without the generated plugin: prove structurally that the canonical plugin
// skill is not discoverable. The system/init plugin state must be exactly the
// pinned builtins (no plugin tuple), any Skill attempt naming the router —
// canonical or bare — must fail, and when system/init reports a skills
// inventory it must name neither plugin skill; at least one of those two
// proofs must be present; the release marker must not appear.
function inspectControlRun(result, label) {
  const events = parseStreamEvents(result.stdout, label);
  const { sessionId, inventory } = inspectInit(events, label);
  assertResultSuccess(events, label);
  let proven = false;
  if (Object.keys(inventory).length > 0) {
    const names = Object.values(inventory).flat();
    assert.ok(!names.some((name) => ROUTER_SKILL_ALIASES.has(name)),
      `${label}: system/init reported the router skill without the generated plugin`);
    assert.ok(!names.some((name) => RELEASE_SKILL_ALIASES.has(name)),
      `${label}: system/init reported the release skill without the generated plugin`);
    proven = true;
  }
  const results = toolResults(events);
  const attempts = toolUses(events).filter((use) => use.name === "Skill" && ROUTER_SKILL_ALIASES.has(skillName(use.input)));
  for (const attempt of attempts) {
    const outcome = results.get(attempt.id);
    assert.ok(outcome, `${label}: Skill(${CLAUDE_ROUTER_SKILL_ID}) attempt produced no tool_result`);
    assert.equal(outcome.isError, true, `${label}: Skill(${CLAUDE_ROUTER_SKILL_ID}) loaded without the generated plugin`);
    proven = true;
  }
  const releaseLoads = toolUses(events).filter((use) => use.name === "Skill" && RELEASE_SKILL_ALIASES.has(skillName(use.input)));
  assert.equal(releaseLoads.length, 0, `${label}: control loaded the release skill without the generated plugin`);
  assert.ok(proven, `${label}: control produced no structural proof of router discoverability (no skills inventory in system/init and no Skill attempt); refine the control prompt`);
  assert.ok(!assistantTexts(events).some((entry) => entry.text.includes(RELEASE_MARKER)), `${label}: without-plugin control surfaced the release marker`);
  return sessionId;
}

// Plugin-exposed runs: require the ordered structural chain
// system/init -> Skill(canonical router) -> Write(token file) -> Bash(route
// --request-token) -> tool_result parsed as router JSON -> Skill(canonical
// selected skill) -> final marker (select), or outcome none with no release
// Skill (abstention). Inventory contents stay advisory: the pinned init has
// omitted plugin skill inventories before, and runtime discovery is proven by
// the correlated successful Skill tool_result below.
function inspectRoutedRun(result, label, expected) {
  const events = parseStreamEvents(result.stdout, label);
  const { initIndex, sessionId } = inspectInit(events, label, fx.pluginDir);
  assertResultSuccess(events, label);
  const results = toolResults(events);
  const routerUse = successfulSkillUse(events, results, CLAUDE_ROUTER_SKILL_ID, label, initIndex);

  let writeUse = null;
  let writtenToken = null;
  for (const candidate of toolUses(events).filter((use) => use.index > routerUse.index && use.name === "Write" && typeof use.input?.file_path === "string")) {
    const match = candidate.input.file_path.replaceAll("\\", "/").match(TOKEN_FILE_PATTERN);
    if (!match) continue;
    const outcome = results.get(candidate.id);
    if (!outcome || outcome.isError === true) continue;
    writeUse = candidate;
    writtenToken = match[1];
    break;
  }
  assert.ok(writeUse, `${label}: agent did not Write the router request token file`);
  assert.equal(typeof writeUse.input.content, "string", `${label}: token file Write had no content`);
  assert.ok(writeUse.input.content.length > 0, `${label}: token file Write content was empty`);
  assert.ok(writeUse.input.content.length <= 100_000, `${label}: token file Write exceeded the router request size limit`);
  const writePath = writeUse.input.file_path.replaceAll("\\", "/");
  assert.ok(writePath.startsWith(`${fx.project.replaceAll("\\", "/")}/`) || writePath.startsWith(`${fx.projectReal.replaceAll("\\", "/")}/`), `${label}: token file was written outside the fixture project`);

  const bashCandidates = toolUses(events).filter(
    (use) => use.index > writeUse.index && use.name === "Bash" && typeof use.input?.command === "string" &&
      use.input.command.includes("skill-router route") && use.input.command.includes("--request-token"),
  );
  assert.ok(bashCandidates.length > 0, `${label}: agent did not Bash the router route command with --request-token`);

  let routeUse = null;
  let routeResult = null;
  let routeOutput = null;
  for (const candidate of bashCandidates) {
    const outcome = results.get(candidate.id);
    if (!outcome || outcome.isError === true) continue;
    try {
      const parsed = JSON.parse(outcome.text);
      if (parsed && typeof parsed === "object" && typeof parsed.outcome === "string") {
        routeUse = candidate;
        routeResult = outcome;
        routeOutput = parsed;
        break;
      }
    } catch {
      // A non-JSON intermediate attempt does not satisfy the structural chain.
    }
  }
  assert.ok(routeUse, `${label}: no matching tool_result parsed as router JSON`);
  assert.equal(routeOutput.outcome, expected.outcome, `${label}: router returned outcome "${sanitizeText(String(routeOutput.outcome))}", expected "${expected.outcome}"`);

  const commandToken = routeUse.input.command.match(/--request-token\s+([a-f0-9]{32})/);
  assert.ok(commandToken, `${label}: route command did not carry a 32-hex --request-token`);
  assert.equal(commandToken[1], writtenToken, `${label}: route command token did not match the written token file`);
  for (const prefix of [fx.project, fx.projectReal]) {
    assert.ok(!existsSync(path.join(prefix, ".skill-router", "requests", `${writtenToken}.txt`)), `${label}: router did not consume the request token file`);
  }

  if (expected.outcome === "select") {
    // The router's public route output keeps the bare public id; Claude must
    // then load the canonical namespaced Skill ID the generated plugin exposes.
    assert.equal(routeOutput.skillId, expected.skillId, `${label}: router selected the wrong skill`);
    assert.equal(expected.skillId, RELEASE_SKILL_ID, `${label}: route output skillId must stay the public id`);
    const releaseUse = successfulSkillUse(events, results, CLAUDE_RELEASE_SKILL_ID, label, routeResult.index);
    const finalText = assistantTexts(events).at(-1);
    assert.ok(finalText, `${label}: run produced no final assistant text`);
    assert.ok(finalText.text.includes(expected.marker), `${label}: final response omitted the hidden skill marker`);
    assert.ok(finalText.index > releaseUse.index, `${label}: marker surfaced before the selected skill loaded`);
  } else {
    const releaseLoads = toolUses(events).filter((use) => use.name === "Skill" && RELEASE_SKILL_ALIASES.has(skillName(use.input)));
    assert.equal(releaseLoads.length, 0, `${label}: unrelated request loaded the release skill`);
    assert.ok(!assistantTexts(events).some((entry) => entry.text.includes(expected.marker)), `${label}: unrelated request surfaced the release marker`);
  }
  return sessionId;
}

// Credential-bearing fixture material is always removed, including under
// KEEP_FIXTURE, which may retain only scrubbed content.
function scrubCredentialMaterial() {
  let removed = 0;
  if (!fx.temporary || !existsSync(fx.temporary)) return { removed };
  const secretPattern = /sk-ant-[A-Za-z0-9_-]{8,}/;
  const visit = (directory) => {
    for (const entry of readdirSync(directory, { withFileTypes: true })) {
      const absolute = path.join(directory, entry.name);
      if (entry.isDirectory() && !entry.isSymbolicLink()) {
        visit(absolute);
        continue;
      }
      let text;
      try {
        text = readFileSync(absolute).toString("utf8");
      } catch {
        continue;
      }
      if ((credential !== "" && text.includes(credential)) || secretPattern.test(text)) {
        rmSync(absolute, { force: true });
        removed += 1;
      }
    }
  };
  visit(fx.temporary);
  return { removed };
}

// Main flow.
let failure = null;
try {
  if (!model) throw gateError("SKILL_ROUTER_CLAUDE_MODEL is required; set it to the Claude model id this validation should exercise");
  if (!credential) throw gateError("Set SKILL_ROUTER_CLAUDE_API_KEY or ANTHROPIC_API_KEY before packing or running");
  fx.claude = resolveExecutable(claudeSetting);

  fx.temporary = mkdtempSync(path.join(os.tmpdir(), "skill-router-claude-e2e-"));
  fx.home = path.join(fx.temporary, "router-home");
  fx.fixtureTmp = path.join(fx.temporary, "tmp");
  const install = path.join(fx.temporary, "install");
  fx.project = path.join(fx.temporary, "project");
  const external = path.join(fx.temporary, "external");
  const initial = path.join(external, "initial");
  const additional = path.join(external, "additional");
  // Registration cache surface: CLAUDE_CONFIG_DIR keeps the CLI's marketplace
  // cache and settings out of the HOME the model runs will see. The local
  // declaration itself lands in the fixture project (cwd = router root).
  fx.registerConfig = path.join(fx.temporary, "register-config");
  mkdirSync(fx.home, { recursive: true, mode: 0o700 });
  mkdirSync(fx.fixtureTmp, { recursive: true, mode: 0o700 });
  mkdirSync(fx.project, { recursive: true });
  mkdirSync(path.join(fx.home, ".claude"), { recursive: true, mode: 0o700 });
  fx.projectReal = realpathSync(fx.project);

  const versionOutput = execute(fx.claude, ["--version"], { env: claudeEnvironment() }).stdout.trim();
  const versionMatch = versionOutput.match(/(\d+)\.(\d+)\.(\d+)/);
  assert.ok(versionMatch, `Claude Code version was unrecognized: ${sanitizeText(versionOutput).slice(0, 100)}`);
  const versionMajor = Number.parseInt(versionMatch[1], 10);
  assert.ok(versionMajor >= 2, `unsupported Claude Code ${versionMajor}.x: this E2E assumes Claude Code 2.x (--bare and the stream-json schema used here)`);
  process.stdout.write(`claude ${versionMatch[0]} accepted\n`);

  section("Pack and install published artifact shape");
  const packed = execute("npm", ["pack", "--silent", "--pack-destination", fx.temporary]).stdout.trim().split("\n").at(-1);
  assert.ok(packed, "npm pack produced no tarball name");
  execute("npm", ["install", "--prefix", install, "--ignore-scripts", path.join(fx.temporary, packed)]);
  fx.router = path.join(install, "node_modules", ".bin", "skill-router");
  try {
    accessSync(fx.router, constants.X_OK);
  } catch {
    throw new Error("installed artifact did not provide an executable skill-router bin");
  }
  fx.routerBin = path.dirname(fx.router);
  process.stdout.write("installed packed artifact\n");

  writeSkill(initial, "release", "Release", "Prepare notes and publish releases", RELEASE_MARKER);
  writeSkill(initial, "deploy-api", "Deploy API", "Deploy a service to production", "DEPLOY_API_LOADED");
  writeSkill(initial, "deploy-web", "Deploy Web", "Deploy a service to production", "DEPLOY_WEB_LOADED");
  writeSkill(additional, "review", "Review", "Review code for correctness", "REVIEW_SKILL_LOADED");
  writeSkill(additional, "format", "Format", "Format source files", "FORMAT_SKILL_LOADED");
  writeFileSync(path.join(fx.project, ".skill-router.json"), `${JSON.stringify({ schemaVersion: 1, sources: [initial] }, null, 2)}\n`);

  const routerEnv = () => ({ ...process.env, SKILL_ROUTER_HOME: fx.home, PWD: fx.project });
  // Registration environment: fixture-local HOME plus an isolated
  // CLAUDE_CONFIG_DIR, so `claude plugin ...` never reads or writes host Claude
  // configuration and never leaves a plugin surface for the model runs.
  const registerEnv = () => ({
    ...routerEnv(),
    HOME: fx.home,
    CLAUDE_CONFIG_DIR: fx.registerConfig,
    CLAUDE_CODE_DISABLE_NONESSENTIAL_TRAFFIC: "1",
    CLAUDE_CODE_DISABLE_SKILLS_SYNC: "1",
    DISABLE_TELEMETRY: "1",
    DISABLE_AUTOUPDATER: "1",
    DISABLE_ERROR_REPORTING: "1",
    DISABLE_BUG_COMMAND: "1",
  });
  const run = (args, options = {}) => execute(fx.router, args, { env: routerEnv(), ...options });
  const jsonWith = (options, ...args) => {
    const separator = args.indexOf("--");
    if (separator === -1) args.push("--json");
    else args.splice(separator, 0, "--json");
    const stdout = run(args, options).stdout;
    try {
      return JSON.parse(stdout);
    } catch {
      throw new Error(`skill-router returned invalid JSON: ${sanitizeText(stdout).slice(0, 500)}`);
    }
  };
  const json = (...args) => jsonWith({}, ...args);

  section("Initialize and exercise every public command");
  const opencodeInit = ["init", "--root", fx.project, "--harness", "opencode"];
  assert.equal(json(...opencodeInit, "--dry-run").dryRun, true);
  assert.equal(json(...opencodeInit).skillCount, 3);
  assert.equal(json(...opencodeInit).skillCount, 3);
  assert.equal(json("route", "--root", fx.project, "--", "release").skillId, "release");
  assert.equal(json("route", "--root", fx.project, "--", "calculate orbital velocity").outcome, "none");
  assert.equal(json("route", "--root", fx.project, "--", "deploy service production").outcome, "clarify");
  assert.deepEqual(json("add", "review", "--root", fx.project, "--source", additional, "--alias", "inspect change", "--description", "Inspect code changes").added, ["review"]);
  assert.equal(json("route", "--root", fx.project, "--", "inspect change").skillId, "review");
  json("add", path.join(additional, "format"), "--root", fx.project, "--no-enable");
  assert.equal(json("route", "--root", fx.project, "--", "format").outcome, "none");
  assert.deepEqual(json("scan", "--root", fx.project).diff, { added: [], removed: [], changed: [] });
  assert.equal(json("check", "--root", fx.project).healthy, true);

  rmSync(path.join(fx.project, ".skill-router", "opencode-skills", "review", "SKILL.md"));
  execute(fx.router, ["check", "--root", fx.project, "--json"], { env: routerEnv(), expectFailure: true });
  json("scan", "--root", fx.project);
  assert.equal(json("check", "--root", fx.project).healthy, true);
  process.stdout.write("router CLI init/route/add/scan/check exercised\n");

  section("Initialize and verify the production Claude integration");
  mkdirSync(fx.registerConfig, { recursive: true });
  // Every project/local command runs with cwd = the fixture project (the
  // adapter passes the router root); only the Claude cache/config root is
  // redirected away from the HOME the model runs will see.
  const registerOptions = { cwd: fx.project, env: registerEnv() };

  const claudeInit = jsonWith(registerOptions, "init", "--root", fx.project, "--harness", "claude");
  assert.deepEqual(claudeInit.harnesses, ["opencode", "claude"], "explicit harness selections are additive");
  assert.equal(claudeInit.claude.scope, "local", "project scope registers the plugin at Claude `local` scope");
  assert.equal(claudeInit.claude.plugin, PLUGIN_NAME, "the generated plugin uses the production namespace");
  assert.equal(claudeInit.claude.skillCount, 3, "every enabled skill was generated into the plugin");
  fx.pluginDir = claudeInit.claude.pluginDirectory;
  fx.pluginSkills = path.join(fx.pluginDir, "skills");
  assert.ok(existsSync(path.join(fx.pluginDir, ".claude-plugin", "plugin.json")), "generated plugin manifest exists");
  assert.equal(
    jsonWith(registerOptions, "check", "--root", fx.project).healthy,
    true,
    "check verifies the generated plugin and the exact registration",
  );

  const installation = JSON.parse(
    readFileSync(path.join(fx.project, ".skill-router", "installation.json"), "utf8"),
  );
  assert.deepEqual(installation.harnesses, ["opencode", "claude"]);
  assert.equal(installation.owner, "skill-router");
  assert.equal(installation.claude.marketplace, claudeInit.claude.marketplace);
  assert.match(installation.claude.marketplace, /^skill-router-[0-9a-f]{24}$/, "marketplace identity is the scoped hash");
  assert.equal(installation.claude.version, claudeInit.claude.version);

  // The exact registration is proven from the project root (every project
  // command runs with cwd = the router root) using the fixture-local config.
  const registered = JSON.parse(execute(fx.claude, ["plugin", "list", "--json"], registerOptions).stdout);
  const reference = `${PLUGIN_NAME}@${installation.claude.marketplace}`;
  const exact = registered.find((entry) => entry.id === reference);
  assert.ok(exact, "the exact plugin reference is registered");
  assert.equal(exact.scope, "local");
  assert.equal(exact.version, installation.claude.version);
  assert.notEqual(exact.enabled, false, "registration stays enabled");

  // Registration lands in exactly one project-owned file and never in the
  // model HOME or as a project-local plugin tree.
  const registrationFile = path.join(fx.project, ".claude", "settings.local.json");
  assert.deepEqual(readdirSync(path.join(fx.project, ".claude")), ["settings.local.json"]);
  const declaration = JSON.parse(readFileSync(registrationFile, "utf8"));
  assert.ok(
    declaration.extraKnownMarketplaces?.[installation.claude.marketplace],
    "the project declares the generated marketplace",
  );
  assert.ok(!existsSync(path.join(fx.project, ".claude-plugin")), "fixture project must not expose a project-local .claude-plugin");
  assert.ok(!existsSync(path.join(fx.home, ".claude", "plugins")), "the model config root must not see the registration");
  assert.ok(!existsSync(path.join(fx.home, ".claude", "skills")), "isolated HOME must not expose .claude/skills");

  // The model sessions below run with `--bare` (no `--restricted`), so the
  // fixture-local declaration is removed again through the official CLI after
  // it has been proven: registration capability is demonstrated above, and the
  // model runs must observe exactly one plugin source — the `--plugin-dir`
  // tree. Removing it through the CLI keeps Claude-owned settings CLI-written.
  execute(fx.claude, ["plugin", "uninstall", reference, "--scope", "local"], registerOptions);
  execute(fx.claude, ["plugin", "marketplace", "remove", installation.claude.marketplace, "--scope", "local"], registerOptions);
  const registrationAfter = readFileSync(registrationFile, "utf8");
  assert.equal(
    JSON.parse(registrationAfter).extraKnownMarketplaces?.[installation.claude.marketplace],
    undefined,
    "the fixture-local declaration was removed before the model runs",
  );

  const managedRoot = path.join(fx.project, ".skill-router", "opencode-skills");
  const registry = JSON.parse(readFileSync(path.join(fx.project, ".skill-router", "registry.json"), "utf8"));
  const expectedIds = [...new Set([ROUTER_SKILL_ID, ...registry.skills.filter((entry) => entry.enabled !== false).map((entry) => entry.id)])].sort();
  assert.deepEqual(listingIds(managedRoot), expectedIds, "managed skill IDs drifted from the enabled registry");
  assert.deepEqual(listingIds(fx.pluginSkills), expectedIds, "generated plugin skills/ IDs drifted from the enabled registry");
  assertPluginLayout(fx.pluginDir, { version: installation.claude.version });

  for (const id of expectedIds) {
    const skillFile = path.join(fx.pluginSkills, id, "SKILL.md");
    assert.ok(existsSync(skillFile), `generated plugin skill missing for ${id}`);
    const text = readFileSync(skillFile, "utf8");
    assert.equal(frontmatterName(text), id, `frontmatter name for plugin skill ${id} does not match its directory ID`);
    assert.ok(!text.includes("opencode/autoinvoke"), `plugin skill ${id} was generated from the OpenCode copy, not its source`);
  }

  // Pre-run snapshot: the generated plugin must survive the model runs intact.
  const pluginManifestBefore = readFileSync(path.join(fx.pluginDir, ".claude-plugin", "plugin.json"), "utf8");
  const skillTreeBefore = treeManifest(fx.pluginSkills);
  process.stdout.write("production plugin verified: inert manifest, exact registration, skill IDs\n");

  section("Validate a without-plugin control run");
  const controlSession = inspectControlRun(runClaude(CONTROL_PROMPT, false), "control");
  process.stdout.write("without-plugin control proved the plugin skill is not discoverable\n");

  section("Validate genuinely fresh plugin-exposed Claude sessions");
  const firstSession = inspectRoutedRun(runClaude(RELEASE_PROMPT, true), "plugin-select", {
    outcome: "select",
    skillId: RELEASE_SKILL_ID,
    marker: RELEASE_MARKER,
  });
  process.stdout.write("release request routed and loaded in a fresh plugin-exposed session\n");
  const secondSession = inspectRoutedRun(runClaude(UNRELATED_PROMPT, true), "plugin-none", { outcome: "none" });
  process.stdout.write("unrelated request abstained in a distinct fresh plugin-exposed session\n");

  assert.notEqual(firstSession, secondSession, "plugin-exposed validation reused a session ID across fresh runs");
  assert.notEqual(controlSession, firstSession, "control validation reused a plugin-exposed session ID");
  assert.notEqual(controlSession, secondSession, "control validation reused a plugin-exposed session ID");

  // The generated plugin survived every run byte-for-byte, and no run created
  // a Claude surface in the fixture project.
  assert.equal(
    readFileSync(path.join(fx.pluginDir, ".claude-plugin", "plugin.json"), "utf8"),
    pluginManifestBefore,
    "generated plugin manifest changed during validation",
  );
  assert.deepEqual(treeManifest(fx.pluginSkills), skillTreeBefore, "generated skills changed during validation");
  assert.equal(
    readFileSync(registrationFile, "utf8"),
    registrationAfter,
    "the model runs must not modify the fixture project Claude settings",
  );

  const syncedSkills = path.join(fx.home, ".claude", "skills");
  if (existsSync(syncedSkills)) {
    assert.equal(readdirSync(syncedSkills).length, 0, "isolated HOME accumulated synced skills during validation");
  }
  section("Validation passed");
} catch (error) {
  failure = error;
} finally {
  const scrubbed = scrubCredentialMaterial();
  if (fx.temporary) {
    if (keepFixture) {
      process.stdout.write(`fixture retained by request; credential-bearing files removed: ${scrubbed.removed}\n`);
    } else {
      rmSync(fx.temporary, { recursive: true, force: true });
    }
  }
}

if (failure) {
  reportFailure(failure);
  process.exitCode = 1;
}
